// === Global Sync Signal ===
reg llm_go_signal = 1;

reg				clk,rst_n;
wire[4:0]		wave;

signal_generator uut(
				.clk(clk),
				.rst_n(rst_n),
				.wave(wave)
				);

reg[31:0]reference[0:99];

integer i = 0;
integer error = 0;
// integer outfile;
initial begin
      $readmemh("../../../tri_gen.txt",reference);
			clk = 0;
      rst_n = 0;
			#10
      rst_n =1;
      // outfile = $fopen("tri_gen.txt", "w");
			repeat(100) begin
        // $fwrite(outfile, "%h\n", wave);
        // $display(wave);
        error=(wave==reference[i])?error:error+1;
        #10;
        i = i+1;
      end
      // $fclose(outfile);
      if(error==0)
      begin
        $display("===========Your Design Passed===========");
            end
      else
      begin
        $display("===========Error===========");
      end
      $finish;
end

always #5 clk =~clk;





        ///////////////////added
        integer file_mantra;
        initial begin
          file_mantra = $fopen("output.txt");//added
          $fwrite(file_mantra, "time, ");
      $fwrite(file_mantra, "wave,");

          $fwrite(file_mantra, "\n");//added
          forever begin
            #1
            $fwrite(file_mantra, "%0d, ", $time);
        $fwrite(file_mantra, "%h, ", wave);

            $fwrite(file_mantra, "\n");
          end
        end





// ============================================
// === LLM Enhanced Stimuli (Phase 1) ===
initial begin
    // [Auto-Moved Vars]
        integer i;

    // 1. DECLARE VARIABLES FIRST (Top of block)


    // 2. THEN WAIT for original tests
    wait(llm_go_signal == 1);

    // 3. THEN execute logic

    // --- Initialization ---
    // Ensure reset is asserted at the start to bring DUT to known state
    rst_n = 0;
    repeat(5) @(posedge clk);

    // Release reset on negedge to avoid setup/hold violations
    @(negedge clk);
    rst_n = 1;

    // --- Phase 1: Full Triangle Wave Traversal ---
    // Wait for the counter to reach the maximum value (31)
    // This exercises the 'Count Up' logic and the 'State 0 -> State 1' transition condition
    wait(wave == 5'b11111);

    // Wait for the counter to return to minimum value (0)
    // This exercises the 'Count Down' logic and the 'State 1 -> State 0' transition condition
    wait(wave == 5'b00000);

    // --- Phase 2: Asynchronous Reset Sensitivity Test ---
    // Allow the counter to increment partially (e.g., to ~10)
    repeat(10) @(posedge clk);

    // Assert reset asynchronously (away from clock edge)
    // This targets mutations that might remove 'negedge rst_n' from the sensitivity list
    #2; 
    rst_n = 0;
    #7; // Hold low for a duration not aligned with clock period
    rst_n = 1;

    // --- Phase 3: Boundary Condition Interruption (Peak) ---
    // Wait for the wave to reach the peak again
    wait(wave == 5'b11111);

    // Assert reset exactly when wave is at peak
    // This stresses the logic where 'state' and 'wave' might be updating simultaneously
    @(negedge clk);
    rst_n = 0;
    @(negedge clk);
    rst_n = 1;

    // --- Phase 4: Boundary Condition Interruption (Valley) ---
    // Wait for the wave to reach the valley (0)
    wait(wave == 5'b00000);

    // Assert reset exactly when wave is at 0
    @(negedge clk);
    rst_n = 0;
    @(negedge clk);
    rst_n = 1;

    // --- Phase 5: Rapid Toggling / Glitch Test ---
    // Stress test the reset recovery logic
    repeat(5) @(posedge clk);
    rst_n = 0;
    #2; rst_n = 1;
    #2; rst_n = 0;
    #2; rst_n = 1;

    // Stabilize before handing over control
    repeat(20) @(posedge clk);

    // 4. Cleanup
    // Handover control to the original testbench
    llm_go_signal = 0;
end
// ============================================


// === Global Watchdog ===

// === Global Safety Watchdog (Injected) ===
initial begin
    #200000;
    $display("\n[Watchdog] Timeout triggered at %t!", $time);
    if (file_mantra != 0) $fclose(file_mantra);
    $finish;
end

endmodule

